73	    /// Initialize the state runtime using the provided Codex home and default provider.
74	    ///
75	    /// This opens (and migrates) the SQLite database at `codex_home/state.sqlite`.
76	    pub async fn init(
77	        codex_home: PathBuf,
78	        default_provider: String,
79	        otel: Option<OtelManager>,
80	    ) -> anyhow::Result<Arc<Self>> {
81	        tokio::fs::create_dir_all(&codex_home).await?;
82	        remove_legacy_state_files(&codex_home).await;
83	        let state_path = state_db_path(codex_home.as_path());
84	        let existed = tokio::fs::try_exists(&state_path).await.unwrap_or(false);
85	        let pool = match open_sqlite(&state_path).await {
86	            Ok(db) => Arc::new(db),
87	            Err(err) => {
88	                warn!("failed to open state db at {}: {err}", state_path.display());
89	                if let Some(otel) = otel.as_ref() {
90	                    otel.counter(METRIC_DB_INIT, 1, &[("status", "open_error")]);
91	                }
92	                return Err(err);
93	            }
94	        };
95	        if let Some(otel) = otel.as_ref() {
96	            otel.counter(METRIC_DB_INIT, 1, &[("status", "opened")]);
97	        }
98	        let runtime = Arc::new(Self {
99	            pool,
100	            codex_home,
101	            default_provider,
102	        });
103	        if !existed && let Some(otel) = otel.as_ref() {
104	            otel.counter(METRIC_DB_INIT, 1, &[("status", "created")]);
105	        }
106	        Ok(runtime)
107	    }
108	
109	    /// Return the configured Codex home directory for this runtime.
110	    pub fn codex_home(&self) -> &Path {
111	        self.codex_home.as_path()
112	    }
113	}
