131	pub fn state_db_filename() -> String {
132	    format!("{STATE_DB_FILENAME}_{STATE_DB_VERSION}.sqlite")
133	}
134	
135	pub fn state_db_path(codex_home: &Path) -> PathBuf {
136	    codex_home.join(state_db_filename())
137	}
